import sys

def solve(n, edges, s, t):
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: float('inf') for i in range(n)}
    dist[s] = 0

    visited = [False] * n

    def bfs():
        queue = [s]
        visited[s] = True

        while queue:
            u = queue.pop(0)
            for v, w in graph[u]:
                if not visited[v] and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    visited[v] = True
                    queue.append(v)

    bfs()

    if dist[t] == float('inf'):
        return -1
    else:
        return int(dist[t])
