import math

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [math.inf] * n
    dist[s] = 0
    visited = [False] * n

    for _ in range(n):
        u = -1
        for v in range(n):
            if not visited[v] and (u == -1 or dist[v] < dist[u]):
                u = v

        if u == -1:
            break

        visited[u] = True

        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    if dist[t] == math.inf:
        return -1
    else:
        return int(dist[t])
