```python
def solve(n, edges, s, t):
    """
    Calculates the shortest path from node s to node t in a directed weighted graph.

    Args:
        n: The number of nodes in the graph (0-indexed).
        edges: A list of tuples, where each tuple represents a directed edge
               (u, v, w) from node u to node v with weight w.
        s: The starting node.
        t: The target node.

    Returns:
        The minimum total weight of a path from s to t as an integer.
        Returns 0 if s == t.
        Returns -1 if t cannot be reached from s.
    """

    if s == t:
        return 0

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    distances = {}
    for node in range(n):
        distances[node] = float('inf')

    distances[s] = 0

    visited = set()

    import heapq
    priority_queue = [(0, s)]  # (distance, node)

    while priority_queue:
        dist, u = heapq.heappop(priority_queue)

        if u in visited:
            continue
        visited.add(u)

        if u in graph:
            for v, w in graph[u]:
                if distances[v] > distances[u] + w:
                    distances[v] = distances[u] + w
                    heapq.heappush(priority_queue, (distances[v], v))

    if distances[t] == float('inf'):
        return -1
    else:
        return distances[t]
```

