def solve(n, edges, s, t):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    q = [(s, 0)]
    visited = [False] * n
    visited[s] = True

    while q:
        u, d = q.pop(0)
        if u == t:
            return d

