def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []

    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    if start == goal:
        return [start]

    visited = set()
    path = []

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and (row, col) not in visited

    def dfs(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True

        visited.add((row, col))
        path.append((row, col))

        # Explore adjacent cells
        if is_valid(row + 1, col) and dfs(row + 1, col):
            return True
        if is_valid(row - 1, col) and dfs(row - 1, col):
            return True
        if is_valid(row, col + 1) and dfs(row, col + 1):
            return True
        if is_valid(row, col - 1) and dfs(row, col - 1):
            return True

        path.pop() # Backtrack if no path found from this cell
        return False

    if dfs(start[0], start[1]):
        return path
    else:
        return []
