def solve(haystack: str, needle: str) -> int:
    """
    Given two strings haystack and needle, return the index of the first position
    in haystack where needle is a contiguous subarray.
    """
    if len(needle) > len(haystack):
        return -1
    for i in range(len(haystack) - len(needle) + 1):
        if haystack[i:i + len(needle)] == needle:
            return i
    return -1
