def solve(intervals):
    if not intervals:
        return 0

    intervals.sort(key=lambda x: x[0])  # Sort by start time

    merged_intervals = []
    current_interval = intervals[0]

    for i in range(1, len(intervals)):
        next_interval = intervals[i]

        if next_interval[0] <= current_interval[1]:
            # Overlapping intervals, merge them
            current_interval = (current_interval[0], max(current_interval[1], next_interval[1]))
        else:
            # Non-overlapping interval, add the current interval to the merged list
            merged_intervals.append(current_interval)
            current_interval = next_interval

    merged_intervals.append(current_interval)  # Add the last interval

    return len(intervals) - len(merged_intervals)
