def solve(nums):
    """
    Given a list of integers, return the length of the longest strictly increasing subsequence of nums.
    A subsequence keeps the original order of the chosen elements but need not be contiguous, and strictly increasing
    means each chosen value is larger than the one before it.
    """
    tails = []
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num
    return len(tails)
```

