def solve(nums):
    """
    Calculates the length of the longest strictly increasing subsequence of a list of integers.

    Args:
        nums: A list of integers.

    Returns:
        The length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    tails = []  # tails[i] is the smallest tail of all increasing subsequences with length i+1.

    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            # Binary search to find the smallest tail that is greater than or equal to the current number.
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num

    return len(tails)
