    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [0] * n  # 0: uncolored, 1: red, 2: blue

    def is_bipartite(node, color):
        colors[node] = color
        for neighbor in adj[node]:
            if colors[neighbor] == 0:
                if not is_bipartite(neighbor, 3 - color):
                    return False
            elif colors[neighbor] == color:
                return False
        return True

    for i in range(n):
        if colors[i] == 0:
            if not is_bipartite(i, 1):
                return True

    return False
