def solve(n, edges):
    """
    Checks if an undirected graph contains a cycle.

    Args:
        n: The number of nodes in the graph.
        edges: A list of edges, where each edge is a pair of nodes (u, v).

    Returns:
        True if the graph contains a cycle, False otherwise.
    """
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False
```

