def solve(n, edges):
    """
    Checks if an undirected graph contains a cycle.

    Args:
        n: The number of nodes in the graph (0 to n-1).
        edges: A list of edges, where each edge is a tuple (u, v).

    Returns:
        True if the graph has a cycle, False otherwise.
    """
    if n <= 0:
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n

    def dfs(node, parent):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False
```

